import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {string} imageUrl
 * @property {Object} position   // {x:number,y:number,z:number}
 * @property {Object} rotation   // {x:number,y:number,z:number}
 * @property {Object} scale      // {x:number,y:number,z:number}
 * @property {Array} cinematicPrimitives
 * @property {Array} textContent   // [{ text:string, role:string, size:number, weight:number }]
 * @property {Object} colors        // {ink:string,paper:string,accent:string,surface:string}
 */

/**
 * @typedef {Object} NodeContext
 * @property {Object} textureLoader   // { load: (url:string)=>THREE.Texture }
 * @property {Object} primitives      // record of primitive functions
 * @property {Object} fontAtlas        // { createText: (options)=>THREE.Mesh }
 */

/**
 * Create a textured plane with MSDF text overlay.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // Root container
  const root = new THREE.Object3D();

  // ----- TEXTURED PLANE -----
  const texture = ctx.textureLoader.load(config.imageUrl);
  const material = new MeshBasicNodeMaterial({ map: texture });
  const geometry = new THREE.PlaneGeometry(1, 1);
  const plane = new THREE.Mesh(geometry, material);
  plane.position.set(
    config.position?.x ?? 0,
    config.position?.y ?? 0,
    config.position?.z ?? 0
  );
  plane.rotation.set(
    config.rotation?.x ?? 0,
    config.rotation?.y ?? 0,
    config.rotation?.z ?? 0
  );
  plane.scale.set(
    config.scale?.x ?? 1,
    config.scale?.y ?? 1,
    config.scale?.z ?? 1
  );
  root.add(plane);

  // ----- TEXT OVERLAY (MSDF) -----
  // Expect a single headline entry; fallback if missing.
  const textSpec = (config.textContent && config.textContent[0]) || {
    text: '',
    role: 'headline',
    size: 0.96, // scene‑unit approximation for 96px @ base scale
    weight: 400,
  };

  const textMesh = ctx.fontAtlas.createText({
    text: textSpec.text,
    fontFamily: 'Lora',
    weight: textSpec.weight,
    size: textSpec.size,
    color: new THREE.Color(config.colors?.ink ?? '#16161d'),
    // Align center
    anchorX: 0.5,
    anchorY: 0.5,
  });

  // Position text slightly in front of the plane to avoid z‑fighting
  textMesh.position.set(
    0,
    0,
    0.001
  );

  root.add(textMesh);

  // ----- APPLY CINEMATIC PRIMITIVES (if any) -----
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      const fn = ctx.primitives?.[primitive.name];
      if (typeof fn === 'function') {
        fn(root, primitive.params);
      }
    }
  }

  // ----- USER DATA -----
  root.userData.handlers = {}; // no interaction handlers defined

  const timelines = []; // placeholder for potential GSAP timelines

  root.userData.cleanup = () => {
    // Dispose geometry & material
    geometry.dispose();
    material.dispose();
    texture.dispose();

    // Dispose text resources
    if (textMesh) {
      if (textMesh.geometry) textMesh.geometry.dispose();
      if (textMesh.material) {
        if (Array.isArray(textMesh.material)) {
          textMesh.material.forEach(m => m.dispose());
        } else {
          textMesh.material.dispose();
        }
      }
    }

    // Kill any GSAP timelines
    timelines.forEach(tl => tl.kill());
  };

  return root;
}
